  async function startLogin(prompt='login'){prompt=typeof prompt==='string'?prompt:'login';const c=state.authConfig,verifier=randomValue(),oidcState=randomValue(),nonce=randomValue();sessionStorage.setItem('oidc_transaction',JSON.stringify({verifier,state:oidcState,nonce,createdAt:Date.now()}));const p=new URLSearchParams({client_id:c.client_id,response_type:'code',redirect_uri:c.redirect_uri,scope:c.scope,state:oidcState,nonce,code_challenge:await challenge(verifier),code_challenge_method:'S256',prompt});if(c.audience)p.set('audience',c.audience);location.assign(`${c.authorization_endpoint}?${p}`);}
  async function finishLogin(c){const p=new URLSearchParams(location.search),code=p.get('code'),returnedState=p.get('state'),error=p.get('error');if(error){history.replaceState({},'',location.pathname);if(error==='login_required'){sessionStorage.removeItem('oidc_session_seen');return false;}throw new Error(`OIDC_AUTHORIZATION_FAILED_${error.toUpperCase().replace(/[^A-Z0-9]+/g,'_')}`);}if(!code){if(sessionStorage.getItem('oidc_session_seen')==='1')await startLogin('none');return false;}let tx;try{tx=JSON.parse(sessionStorage.getItem('oidc_transaction')||'null');}catch{tx=null;}sessionStorage.removeItem('oidc_transaction');history.replaceState({},'',location.pathname);if(!tx||tx.state!==returnedState||Date.now()-tx.createdAt>600000)throw new Error('OIDC_STATE_INVALID');const body=new URLSearchParams({grant_type:'authorization_code',client_id:c.client_id,code,redirect_uri:c.redirect_uri,code_verifier:tx.verifier});const response=await fetch(c.token_endpoint,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});if(!response.ok)throw new Error('OIDC_TOKEN_EXCHANGE_FAILED');const tokens=await response.json();if(typeof tokens.access_token!=='string')throw new Error('OIDC_ACCESS_TOKEN_MISSING');state.accessToken=tokens.access_token;sessionStorage.setItem('oidc_session_seen','1');return true;}
