  async function loadHistory(){if(!client.value)return clearHistory('Выберите клиента, чтобы увидеть последние загрузки.');$('refresh-history').disabled=true;try{const body=await api(`/api/v1/clients/${encodeURIComponent(client.value)}/submissions?limit=20`),list=$('history-list');list.replaceChildren();body.items.forEach(item=>{const row=document.createElement('article');row.className='history-item';const info=document.createElement('div'),title=document.createElement('strong'),date=document.createElement('small');title.textContent=item.schema_id;date.textContent=new Intl.DateTimeFormat('ru',{dateStyle:'medium',timeStyle:'short'}).format(new Date(item.created_at));info.append(title,date);const controls=document.createElement('div');controls.className='history-controls';const badge=document.createElement('span');badge.className=`badge ${item.status==='blocked'?'blocked':''}`;badge.textContent=item.status;controls.append(badge);if(item.status==='accepted'){const open=document.createElement('button');open.type='button';open.className='analysis-open';open.textContent='Открыть анализ';open.addEventListener('click',()=>loadAnalysis(item.submission_id));controls.append(open);}row.append(info,controls);list.append(row);});$('history-empty').textContent=body.items.length?'':'Загрузок пока нет.';$('history-empty').hidden=body.items.length>0;list.hidden=body.items.length===0;}catch{clearHistory('Не удалось загрузить историю. Повторите попытку.');}finally{$('refresh-history').disabled=!client.value;}}
