  async function saveNote(){if(!state.analysisSubmissionId)return;const button=$('save-note'),body=$('note-body').value;button.disabled=true;$('note-status').textContent='Сохраняем…';try{const note=await api(`/api/v1/clients/${encodeURIComponent(client.value)}/submissions/${encodeURIComponent(state.analysisSubmissionId)}/note`,{method:'PATCH',headers:{'Content-Type':'application/json','If-Match':`"${state.noteVersion}"`},body:JSON.stringify({body})});state.noteVersion=note.version;state.noteSavedBody=note.body;$('note-body').value=note.body;$('note-version').textContent=`Версия ${note.version}`;$('note-status').textContent='Изменения сохранены.';}catch(error){if(error.message==='CONSULTANT_NOTE_VERSION_CONFLICT')$('note-status').textContent='Заметка изменена в другом окне. Закройте и откройте анализ заново; ваш текст оставлен в поле.';else $('note-status').textContent=`Не удалось сохранить: ${error.message}.`;button.disabled=false;}}
  const bookingSnapshot=()=>JSON.stringify({status:$('booking-status').value,scheduled_at:$('booking-status').value==='scheduled'&&$('booking-at').value?new Date($('booking-at').value).toISOString():null,contact_note:$('booking-contact').value});
  const localDateTimeValue=value=>{if(!value)return '';const date=new Date(value),offset=date.getTimezoneOffset()*60000;return new Date(date.getTime()-offset).toISOString().slice(0,16);};
  function renderBooking(b){state.bookingVersion=b.version;$('booking-status').value=b.status;$('booking-at').value=localDateTimeValue(b.scheduled_at);$('booking-at').disabled=b.status!=='scheduled';$('booking-contact').value=b.contact_note;$('booking-version').textContent=`Версия ${b.version}`;state.bookingSaved=bookingSnapshot();$('save-booking').disabled=true;$('booking-save-status').textContent=b.version?'Статус сохранён.':'Запись ещё не согласована.';}
