  function renderFatTarget(t){state.fatTargetVersion=t.version;$('fat-energy').value=t.energy_kcal??'';$('fat-weight').value=t.weight_kg??'';$('fat-goal').value=t.goal||'maintain';$('fat-activity').value=t.activity||'moderate';$('fat-reason').value=t.reason||'';$('fat-target-version').textContent=`Версия ${t.version}`;const summary=$('fat-target-summary');summary.replaceChildren();summary.hidden=!t.target_min_g;if(t.target_min_g)[['Доля энергии',`${t.energy_percent_min}–${t.energy_percent_max}%`],['Ориентир в сутки',`${t.target_min_g}–${t.target_max_g} г`],['На килограмм',`${t.grams_per_kg_min}–${t.grams_per_kg_max} г/кг`]].forEach(([label,value])=>{const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;row.append(dt,dd);summary.append(row);});$('fat-guide-note').textContent=({within_50_60:'Расчёт попадает в проверочный коридор 50–60 г.',below_50:'Расчёт ниже 50 г: нужна индивидуальная проверка.',above_60:'Расчёт выше 60 г; это не ошибка, если соответствует калорийности.',not_applicable:''})[t.weight_loss_guide_status]||'';state.fatTargetSaved=fatTargetSnapshot();$('save-fat-target').disabled=true;$('fat-save-status').textContent=t.version?'Ориентир сохранён.':'Заполните энергию и массу.';}
