  function renderCatalogHistory(events){const list=$('catalog-history-list');list.replaceChildren();$('catalog-history-count').textContent=String(events.length);if(!events.length){const empty=document.createElement('p');empty.textContent='Событий пока нет.';list.append(empty);return;}events.forEach(event=>{const item=document.createElement('article'),time=document.createElement('time'),title=document.createElement('strong'),meta=document.createElement('small');item.className='catalog-history-event';time.dateTime=event.occurredAt;time.textContent=new Intl.DateTimeFormat('ru-RU',{dateStyle:'short',timeStyle:'short'}).format(new Date(event.occurredAt));title.textContent=catalogHistoryLabels[event.action]||event.action;meta.textContent=`${event.actorRole==='admin'?'Администратор':event.actorRole||'Система'}${event.actorUserId?` · ${event.actorUserId}`:''} · ${event.reasonCode}`;item.append(time,title,meta);list.append(item);});}
